from reconcile import apply,split,NOTES
s='CL [0.12.0]; PL 0.12 '
a=[]
def add(i,t,reader,sec,home,pkg):a.append((f'R{i:03}',t,reader,sec,home,s+pkg))
add(124,'Only clients receive consumer API grants, for one API in one workspace; roles alone do not open consumer data, the consumer index is filtered to grants, and consumer OpenAPI documents remain publicly readable.','access-admin, integrator','administer','administer/clients','A3b; D412 supersedes Z3')
add(125,'Grants narrow writes by application or record type, combine permissions across grants and permit a relationship when either end is writable; reads remain workspace-wide, and cascades must cover every removed type before revealing impact.','access-admin, integrator','administer','administer/roles-and-grants','Z2 D243/D289–D293; E1 C1')
add(126,'An open change set is shared by authorised workers regardless of creator; submitting freezes it, including release moves, unless the same transaction withdraws its request, and only the submitter or an approver may withdraw.','steward, access-admin','use','use/change-sets','A1 D255/D426; R review')
add(127,'Approval publishes atomically against the submitted version and current publication; send-back requires a comment, secondPerson forbids deciding one’s own request, and migration-and-publish follows the same Publish and approval checks.','steward, access-admin','use','use/change-sets','A1 D425; R review')
add(128,'A used refresh token may recover a navigation race for 30 seconds only while the successor it issued remains unused; older tokens, later reuse or a consumed successor end the session, while a server error during renewal does not sign the browser out.','steward, integrator','integrate','integrate/authentication','R review; amends I2 D269')
add(129,'Local passwords normally need 15–128 characters, cannot equal the username or a common password, and repeated failures slow an account after five attempts and an address after twenty, doubling waits to fifteen minutes without locking the account.','steward, access-admin','administer','administer/sign-in','I1/I2 D252/D271; E1 correction')
add(130,'Passkeys and authenticator factors require a local password; adding or removing a passkey requires password or code proof, passkeys are bound to PUBLIC_URL’s host, and recovery codes remain required after a password reset when a second factor is enabled.','steward, access-admin, operator','administer','administer/sign-in','I4 review; R review; E1 J47.9')
add(131,'A provider identity is matched by issuer and subject, never by email; linking moves provider identities and groups from an otherwise unprivileged new person to an existing active person, deactivates the new person and ends their sessions, preserving history.','access-admin','administer','administer/sign-in-providers','I3/I4a D363/D377/D378; I4 review')
add(132,'Disabling or deleting a sign-in provider ends its sessions; local sign-in can be disabled only after a provider has worked, and the last person keeping local sign-in cannot lose it or be deactivated while local sign-in is off.','access-admin','administer','administer/sign-in-providers','I3/I4a D365/D367/D381')
add(133,'Mail login requires an encrypted verified connection; changing its host or port requires the password again, changing a provider issuer requires its client secret again, and an issuer already used for sign-in cannot change.','access-admin','administer','administer/mail','M1; E1 C6')
add(134,'Mail retries start after 30 seconds and double to one hour, permanently refused recipients fail at once and other failures stop after 24 hours; queued message text is sealed and erased when finished, and an administrator can stop a waiting message.','access-admin, operator','administer','administer/mail','M1')
add(135,'Notice email is off until enabled and needs configured mail and the person’s address; immediate mail includes only unread notices made since enabling and less than 24 hours old, with links but no record or person content, and disabling email leaves inbox notices intact.','steward, operator','use','use/notifications','M2 D432/D433; 0.16 AO3 adds digests')
add(136,'The bell shows at most twenty unread notices; Notifications retains searchable history with kind, workspace, read-state and sort choices, supports bulk read/unread/delete, and permanently deleting notices leaves their subjects intact.','steward','use','use/notifications','NT1 D460–D464')
add(137,'Opening a job, move, migration or change-set review marks that person’s subject notices read, including notices arriving while it is open; deciding a request or confirming or cancelling a waiting job closes the waiting notice, and notices expire after 90 days.','steward, integrator','use','use/notifications','A2/NT1')
add(138,'Workspace approval webhooks share record-event signing, rotation, ordering, retry and resend, but name people without emails and use a workspace source with no consumer API; consumer record events contain no actor.','integrator, access-admin','integrate','integrate/webhooks','A2 D428–D431; Z4 D314')
add(139,'A retired model release cannot be selected for new use, but existing workspaces and change sets keep working and may retain their own release; the default workspace’s release cannot retire, exact reinstallation restores a release, and deletion requires no running, history, profile or mapping reference.','model-admin, operator','model','model/releases','MR1 D457/D458')
add(140,'Before 1.0 each engine release reads only its current schema language, now 0.10; an older stored release can be previewed and raised in place against its hash through the workspace screen or model_release_raise, while invalid or duplicate results are refused.','model-admin, operator','model','model/releases','L2a/UW1')
add(141,'A workspace unavailable because of an old, later or invalid model names its reason and safe alternatives; authorised installers can review a raisable release and reopen it, and background work starts when availability returns without a restart.','model-admin, operator, steward','run','run/troubleshooting','UW1; R review')
add(142,'From 0.12 the management API, consumer contract versions, event and webhook headers, sign-in, setting names and documented commands evolve additively; replacement contracts retain the old version for at least twelve months and two minor releases, while pre-1.0 model schemas follow their separate window.','evaluator, integrator, operator','about','about/compatibility-and-licence','L2 D436–D441')
add(143,'Consumer response documents allow additional fields while requests remain closed; clients tolerate unknown response fields and values, including reserved future survivor, provenance, computed-value and value-type extensions.','integrator','integrate','integrate/compatibility','L2 D440')
add(144,'A running instance offers the AGPL licence and source address; a modified installation sets SOURCE_CODE_URL to its corresponding source, shown in About and the account menu.','evaluator, operator','about','about/compatibility-and-licence','L1 D219')
add(145,'The reference installation serves the application and API from one public address with the database and engine behind web, HTTPS or a trusted terminating proxy, persistent job files, separately supplied secrets, and metrics accessible only inside.','operator','run','run/install','DP1–DP4')
add(146,'Behind a proxy, forwarded caller addresses are trusted only from WEB_TRUSTED_PROXIES; malformed ranges refuse startup, and web responses forbid framing the application.','operator','run','run/security','E1 C3/C5')
add(147,'Webhook rotation signs with the new and previous keys for 24 hours by default, allows zero to seven days, and ends an older overlap on another rotation; receivers accept either signature from a comma-separated header, including on retries.','integrator, access-admin','integrate','integrate/webhooks','K1 D413')
add(148,'Re-sealing replaces encrypted secrets atomically and can check them first, but changing the encryption key also invalidates keyed recovery codes; the command reports how many people need new codes.','operator','run','run/secrets-and-keys','K1 D414; E1 C7')
add(149,'Bulk grants are separate writes, so refused grants leave successful grants in place and retain the failed choice with its reason; bulk group removal is atomic and refuses removal of the last active human Security administrator, including one granted through a group.','access-admin','administer','administer/roles-and-grants','grant dialog; SP1b D402; Z1 D283')
add(150,'A profile’s uploaded file and latest check are isolated by workspace, require Bulk there, and cannot supersede another workspace’s file; check routes require workspaceKey and read no file or check when that workspace has none.','model-admin, integrator','model','model/import-profiles','E1 C2/F5')
add(151,'A record’s history groups changes by day with expandable before/after values, kind and actor filters, ten initial entries and twenty more at a time; publication or type-change entries explicitly say when earlier values were not recorded.','steward','use','use/history','RH1')
r=[]
def rule(i,t,cause,effect,ui,reader,code,pkg,sec,home):r.append((f'L{i}',t,cause,effect,ui,reader,code,s+pkg,sec,home))
rule(38,'Consumer API grants are accepted only for clients.','Consumer and management access are separate','Give people and groups appropriate management roles.','Consumer grant choices belong to clients.','access-admin, integrator','422 CONSUMER_API_CLIENTS_ONLY','A3b','administer','administer/clients')
rule(39,'A submitted change set cannot be edited or moved to another release without withdrawing its request.','Approval binds submitted content','Withdraw the request or explicitly withdraw with the edit.','Waiting for approval and Withdraw request.','steward, integrator','409 CHANGE_SET_SUBMITTED','A1; R review','use','use/change-sets')
rule(40,'Only the submitter or an approver can withdraw a publication request.','Withdrawal action permissions','Ask an authorised person to withdraw.','Withdraw request offered where allowed.','steward, access-admin','403 FORBIDDEN','R review','use','use/change-sets')
rule(41,'Adding or removing a passkey requires password, authenticator or recovery proof.','Protect account credentials even with an open session','Supply proof before changing passkeys.','Password or code prompt.','steward','PROOF_REQUIRED, CODE_INCORRECT, SIGN_IN_SLOWED','I4 review; R review','administer','administer/sign-in')
rule(42,'A provider-only account cannot add local second factors or passkeys.','Local credentials must not bypass the provider','Use the organisation’s provider security.','Password required.','access-admin, steward','409 PASSWORD_REQUIRED','I4 review','administer','administer/sign-in')
rule(43,'A mail server or provider endpoint change cannot reuse the saved secret silently.','Secret is scoped to its original endpoint','Enter the password or client secret again; add a new provider for an issuer already used.','Secret field and actionable refusal.','access-admin','MAIL_PASSWORD_REQUIRED, SIGN_IN_PROVIDER_SECRET_REQUIRED, SIGN_IN_PROVIDER_IN_USE','E1 C6','administer','administer/sign-in-providers')
rule(44,'The default workspace’s model release cannot be retired.','Keep the default’s release usable','Change the default workspace’s release before retiring it.','Retire refusal.','model-admin','409 MODEL_RELEASE_IS_DEFAULT','MR1','model','model/releases')
rule(45,'A retired release remains valid for existing users but cannot be chosen for new use elsewhere.','Release lifecycle','Restore the release or choose a usable one; the current change-set pin may remain.','Retired releases hidden from pickers.','model-admin','409 MODEL_RELEASE_RETIRED','MR1','model','model/releases')
rule(46,'A login for SMTP cannot be saved over an unencrypted connection.','Mail credential protection','Choose TLS or STARTTLS and a verified server.','Mail settings refusal.','access-admin','','M1','administer','administer/mail')
rule(47,'A publication performed by a workspace migration still needs Publish and satisfies the approval policy.','One publication authorization rule','Obtain approval or the necessary publishing permissions.','Migration confirmation explains refusal.','model-admin, access-admin','APPROVAL_REQUIRED, FORBIDDEN','R review','model','model/migrations')
rule(48,'Changing the encryption key invalidates existing recovery codes even after encrypted secrets are re-sealed.','Recovery codes use the key directly','Have affected people generate new recovery codes.','CLI reports affected count.','operator','','E1 C7','run','run/secrets-and-keys')
